Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Ltac lit_pc := lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?p) _ _ _ _) => let v := eval vm_compute in p in change p with v end.
(* [comment removed for export] *)
Ltac fbr :=
  lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    lazymatch c with context [bword ?t] => lazymatch t with true => fail | false => fail | _ => destruct t end end
  end; br.
(* [comment removed for export] *)
Ltac dwalk stops := repeat (tryif at_stop stops then fail else first [fbr | awalk1]).
(* [comment removed for export] *)
Ltac fsa := repeat (first [assumption | apply fs_agree_refl | apply fs_agree_set_other; [reflexivity|] ]).

Section DEC.
Variables (ra sp gp tp t0 t1 t2 s0 a1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F0 : bvmap 5 word) (m : mem) (po : Z).
(* [comment removed for export] *)
Hypothesis PO0 : 0 < po.
Hypothesis PO4 : po mod 4 = 0.
Hypothesis POHI : 0x10007fff8000 <= po.
Hypothesis POTOP : po + 4 <= USTACK_TOP - 16.
Hypothesis ACC : acc asegs m po 4.
Hypothesis PC0 : rw_cells asegs m po [C4 (Z_to_bv 64 0)].
Hypothesis MI : mem_inv asegs m.

Definition dec_exit : machine_state -> Prop :=
  fun ms' => exists (a2' a3' a4' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem) (o : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (po / 8 + SHB)) (Z_to_bv 64 po) a1 a2' a3' a4' a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 mod_jn) fc' None m' (seg_rom asegs)
    /\ frm0 fc' /\ fs_agree F0 F' /\ 0 <= o <= 4 /\ rw_cells asegs m' po [C4 (Z_to_bv 64 o)]
    /\ munch [(po, po + 4)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Ltac dec_done0 :=
  apply evt_done; unfold dec_exit; eexists _, _, _, _, _, m, 0;
  split; [unfold mod_jn, e_makeOrientDecision; norm_regset; reflexivity|];
  split; [assumption|]; split; [fsa|]; split; [clear; lia|]; split; [exact PC0|];
  split; [apply munch_refl|]; split; [apply wmono_refl| exact MI].

(* [comment removed for export] *)
